"""Check catalog + generator for Phase 1 (sample-data-driven) audits.

Each entry in CHECK_CATALOG describes one audit check: its category, a
relative importance `weight` within that category (so trivial checks like
"has a favicon" can't tank a score the way "has HTTPS" should be able to),
and a set of possible outcomes with realistic business-friendly copy.

`run_checks(site_profile)` deterministically rolls an outcome for every
check using a seeded RNG (seeded from the URL), so the same URL always
produces the same demo audit. This function is the seam Phase 2 replaces
with checks driven by real crawl data — the output shape (list of check
dicts) stays the same either way, so scoring.py and recommendations.py
never need to change.
"""
import random

STATUS_PASS = "PASS"
STATUS_WARNING = "WARNING"
STATUS_FAIL = "FAIL"
STATUS_NOT_DETECTED = "NOT_DETECTED"
STATUS_NOT_APPLICABLE = "NOT_APPLICABLE"


def _pick(rng: random.Random, outcomes: dict) -> str:
    """Pick a status key from an outcomes dict using each entry's 'prob' weight."""
    keys = list(outcomes.keys())
    weights = [outcomes[k]["prob"] for k in keys]
    return rng.choices(keys, weights=weights, k=1)[0]


