def run_checks(site_profile: dict) -> list[dict]:
    """Roll deterministic outcomes for every check in the catalog.

    Returns a list of dicts shaped for direct persistence as AuditCheck rows
    (see models.AuditCheck), plus recommendation fields when the outcome
    signals a fix is available.
    """
    rng = random.Random(site_profile["seed"])
    results = []
    for check_def in CHECK_CATALOG:
        status = _pick(rng, check_def["outcomes"])
        outcome = check_def["outcomes"][status]
        results.append({
            "category": check_def["category"],
            "key": check_def["key"],
            "name": check_def["name"],
            "weight": check_def["weight"],
            "status": status,
            "result": outcome["result"],
            "raw_value": outcome.get("raw"),
            "expected_value": outcome.get("expected"),
            "business_explanation": outcome.get("why"),
            "data_source": site_profile.get("data_source", "sample_data"),
            # Recommendation fields (present only for actionable non-pass outcomes)
            "rec_title": outcome.get("rec_title"),
            "rec_action": outcome.get("action"),
            "rec_impact": outcome.get("impact"),
            "rec_effort": outcome.get("effort"),
            "rec_difficulty": outcome.get("difficulty"),
        })
    return results
